import{_ as a,o as d,c as e,ag as n}from"./chunks/framework.i8sMDeRW.js";const b=JSON.parse('{"title":"AI 产品数据隐私与合规","description":"","frontmatter":{},"headers":[],"relativePath":"guide/10-compliance/privacy-compliance.md","filePath":"guide/10-compliance/privacy-compliance.md","lastUpdated":1778822679000}'),r={name:"guide/10-compliance/privacy-compliance.md"};function s(l,t,i,p,o,h){return d(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="ai-产品数据隐私与合规" tabindex="-1">AI 产品数据隐私与合规 <a class="header-anchor" href="#ai-产品数据隐私与合规" aria-label="Permalink to &quot;AI 产品数据隐私与合规&quot;">​</a></h1><blockquote><p><strong>2026-05 更新版</strong>：AI 产品隐私风险已经从“对话会不会被训练”扩展到 Agent 工具调用、MCP 连接器、企业上下文、跨境处理、长期记忆和审计 trace。本文提供面向 AI PM 的隐私与合规产品设计框架，不构成法律意见，落地前应由法务按地区和业务场景复核。</p></blockquote><hr><h2 id="_1-ai-产品隐私的独特性" tabindex="-1">1. AI 产品隐私的独特性 <a class="header-anchor" href="#_1-ai-产品隐私的独特性" aria-label="Permalink to &quot;1. AI 产品隐私的独特性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>传统软件</th><th>AI 产品</th></tr></thead><tbody><tr><td>数据类型</td><td>注册信息、行为日志、交易数据</td><td>用户输入、文件、语音、图片、代码、业务上下文、工具返回值</td></tr><tr><td>风险边界</td><td>数据库和业务系统</td><td>模型、上下文窗口、RAG、Agent 工具、记忆、日志、第三方模型</td></tr><tr><td>用户感知</td><td>用户知道自己提交了什么</td><td>用户常不知道系统带入了哪些上下文</td></tr><tr><td>删除难度</td><td>删除数据库记录为主</td><td>还要处理索引、embedding、缓存、日志、训练集、trace</td></tr><tr><td>监管关注</td><td>隐私、数据安全</td><td>隐私 + 自动化决策 + AI 透明度 + 高风险用途</td></tr></tbody></table><p>AI 产品经理要重点关注：</p><ul><li>用户输入是否包含 PII、商业机密、健康信息、未成年人数据；</li><li>文件、图片、语音、代码是否被长期保存或用于训练；</li><li>RAG 检索是否可能越权带入无关文档；</li><li>Agent 工具是否把数据发送到第三方系统；</li><li>长期记忆是否跨会话、跨团队、跨权限边界复用；</li><li>trace 和审计日志是否含敏感数据；</li><li>是否清楚告知用户模型供应商、数据用途、留存和删除机制。</li></ul><hr><h2 id="_2-数据流梳理" tabindex="-1">2. 数据流梳理 <a class="header-anchor" href="#_2-数据流梳理" aria-label="Permalink to &quot;2. 数据流梳理&quot;">​</a></h2><p>隐私合规的第一步不是写政策，而是画清楚数据流。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户输入 / 文件 / 语音 / 图片</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>前端采集与上传</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>后端编排：Prompt / RAG / 工具 / Agent Runtime</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>模型供应商 / 私有模型 / Embedding / Reranker</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>工具调用：搜索、数据库、SaaS API、代码沙箱、MCP Server</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>输出、日志、trace、缓存、长期记忆、评估样例</span></span></code></pre></div><h3 id="_2-1-数据分类" tabindex="-1">2.1 数据分类 <a class="header-anchor" href="#_2-1-数据分类" aria-label="Permalink to &quot;2.1 数据分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数据类型</th><th>示例</th><th>风险</th></tr></thead><tbody><tr><td>账户数据</td><td>邮箱、手机号、组织、支付信息</td><td>身份识别和账单风险</td></tr><tr><td>用户输入</td><td>聊天、Prompt、上传文件</td><td>可能含 PII 和商业机密</td></tr><tr><td>派生数据</td><td>摘要、embedding、标签、评分</td><td>可能反推出原始内容</td></tr><tr><td>工具数据</td><td>API 返回值、数据库查询结果</td><td>可能越权或跨系统泄露</td></tr><tr><td>记忆数据</td><td>用户偏好、历史事实、组织知识</td><td>长期复用风险高</td></tr><tr><td>审计数据</td><td>输入、输出、工具参数、审批记录</td><td>合规必要但敏感</td></tr><tr><td>训练 / 评估数据</td><td>失败样例、人工标注、线上样本</td><td>二次使用需明确授权</td></tr></tbody></table><h3 id="_2-2-数据用途分层" tabindex="-1">2.2 数据用途分层 <a class="header-anchor" href="#_2-2-数据用途分层" aria-label="Permalink to &quot;2.2 数据用途分层&quot;">​</a></h3><table tabindex="0"><thead><tr><th>用途</th><th>是否服务必要</th><th>推荐用户控制</th></tr></thead><tbody><tr><td>提供本次回答</td><td>是</td><td>不可关闭，但应告知</td></tr><tr><td>保存历史记录</td><td>不一定</td><td>可配置保存期限</td></tr><tr><td>生成长期记忆</td><td>不一定</td><td>默认谨慎，允许查看和删除</td></tr><tr><td>安全审核</td><td>通常必要</td><td>告知用途和留存</td></tr><tr><td>产品分析</td><td>不一定</td><td>聚合 / 去标识化优先</td></tr><tr><td>模型训练 / 微调</td><td>通常非必要</td><td>Opt-in 或企业合同明确约定</td></tr><tr><td>人工审阅</td><td>非必要或特定场景必要</td><td>明确告知、最小化、留痕</td></tr></tbody></table><hr><h2 id="_3-全球主要法规与产品影响" tabindex="-1">3. 全球主要法规与产品影响 <a class="header-anchor" href="#_3-全球主要法规与产品影响" aria-label="Permalink to &quot;3. 全球主要法规与产品影响&quot;">​</a></h2><blockquote><p>法规会持续变化，以下为 PM 视角的产品影响摘要。具体法律义务应由法务确认。</p></blockquote><h3 id="_3-1-中国-pipl-数据安全-生成式-ai-相关要求" tabindex="-1">3.1 中国 PIPL / 数据安全 / 生成式 AI 相关要求 <a class="header-anchor" href="#_3-1-中国-pipl-数据安全-生成式-ai-相关要求" aria-label="Permalink to &quot;3.1 中国 PIPL / 数据安全 / 生成式 AI 相关要求&quot;">​</a></h3><table tabindex="0"><thead><tr><th>关注点</th><th>产品实现</th></tr></thead><tbody><tr><td>告知同意</td><td>隐私政策 + AI 数据处理专项说明</td></tr><tr><td>最小必要</td><td>不默认收集与服务无关的数据</td></tr><tr><td>个人信息权利</td><td>查询、复制、导出、更正、删除、撤回同意</td></tr><tr><td>敏感个人信息</td><td>单独同意、必要性说明、严格保护</td></tr><tr><td>自动化决策</td><td>提供解释、拒绝或人工复核通道</td></tr><tr><td>跨境传输</td><td>数据出境评估、合同、单独同意等合规路径</td></tr><tr><td>未成年人</td><td>年龄识别、监护人同意、未成年人模式</td></tr><tr><td>生成式 AI</td><td>内容安全、真实性、投诉机制、数据来源合法性</td></tr></tbody></table><h3 id="_3-2-gdpr-eu-ai-act" tabindex="-1">3.2 GDPR / EU AI Act <a class="header-anchor" href="#_3-2-gdpr-eu-ai-act" aria-label="Permalink to &quot;3.2 GDPR / EU AI Act&quot;">​</a></h3><table tabindex="0"><thead><tr><th>关注点</th><th>产品实现</th></tr></thead><tbody><tr><td>GDPR 知情权</td><td>说明处理目的、法律基础、接收方、保留期限</td></tr><tr><td>访问 / 删除 / 可携带</td><td>数据导出、删除、账户关闭流程</td></tr><tr><td>DPIA</td><td>高风险 AI 或大规模敏感数据处理应做影响评估</td></tr><tr><td>自动化决策</td><td>对重大影响决策提供人工介入和解释</td></tr><tr><td>数据泄露通知</td><td>建立 72 小时内评估和通知机制</td></tr><tr><td>EU AI Act</td><td>按用途判断是否属于禁止 / 高风险 / GPAI / 透明度义务</td></tr><tr><td>高风险系统</td><td>需要风险管理、数据治理、日志、透明度、人类监督</td></tr></tbody></table><h3 id="_3-3-ccpa-cpra、coppa-等" tabindex="-1">3.3 CCPA / CPRA、COPPA 等 <a class="header-anchor" href="#_3-3-ccpa-cpra、coppa-等" aria-label="Permalink to &quot;3.3 CCPA / CPRA、COPPA 等&quot;">​</a></h3><table tabindex="0"><thead><tr><th>法规</th><th>产品关注点</th></tr></thead><tbody><tr><td>CCPA / CPRA</td><td>告知、访问、删除、选择退出出售/共享、敏感信息限制使用</td></tr><tr><td>COPPA</td><td>13 岁以下儿童需家长同意，数据最小化，家长可查看删除</td></tr><tr><td>行业法规</td><td>医疗、金融、教育、雇佣等场景可能有额外要求</td></tr></tbody></table><hr><h2 id="_4-产品合规设计" tabindex="-1">4. 产品合规设计 <a class="header-anchor" href="#_4-产品合规设计" aria-label="Permalink to &quot;4. 产品合规设计&quot;">​</a></h2><h3 id="_4-1-隐私设置面板" tabindex="-1">4.1 隐私设置面板 <a class="header-anchor" href="#_4-1-隐私设置面板" aria-label="Permalink to &quot;4.1 隐私设置面板&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>隐私与数据设置</span></span>
<span class="line"><span>├── 对话保存期限：不保存 / 30 天 / 90 天 / 永久</span></span>
<span class="line"><span>├── 长期记忆：开启 / 关闭 / 查看与删除记忆</span></span>
<span class="line"><span>├── 数据用于模型改进：开启 / 关闭</span></span>
<span class="line"><span>├── 人工审阅：允许 / 不允许 / 仅安全事件</span></span>
<span class="line"><span>├── 我的数据：导出 / 删除对话 / 删除账户</span></span>
<span class="line"><span>├── 连接器权限：查看已连接工具 / 撤销授权</span></span>
<span class="line"><span>└── 企业策略：由管理员管理的项目说明</span></span></code></pre></div><h3 id="_4-2-敏感信息保护" tabindex="-1">4.2 敏感信息保护 <a class="header-anchor" href="#_4-2-敏感信息保护" aria-label="Permalink to &quot;4.2 敏感信息保护&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>机制</th></tr></thead><tbody><tr><td>输入前</td><td>提醒用户不要上传敏感信息</td></tr><tr><td>输入中</td><td>PII / 密钥 / 健康 / 财务信息检测</td></tr><tr><td>发送前</td><td>自动脱敏、二次确认或阻断</td></tr><tr><td>处理时</td><td>最小上下文、权限过滤、数据区域控制</td></tr><tr><td>输出后</td><td>敏感实体脱敏、来源标注、下载权限控制</td></tr><tr><td>日志中</td><td>日志脱敏、访问控制、分级留存</td></tr></tbody></table><h3 id="_4-3-长期记忆治理" tabindex="-1">4.3 长期记忆治理 <a class="header-anchor" href="#_4-3-长期记忆治理" aria-label="Permalink to &quot;4.3 长期记忆治理&quot;">​</a></h3><p>长期记忆是 2026 年 AI 产品隐私的重点风险。</p><table tabindex="0"><thead><tr><th>设计项</th><th>要求</th></tr></thead><tbody><tr><td>可见</td><td>用户能看到系统记住了什么</td></tr><tr><td>可改</td><td>用户能编辑错误记忆</td></tr><tr><td>可删</td><td>用户能删除单条或全部记忆</td></tr><tr><td>可关</td><td>用户能关闭长期记忆</td></tr><tr><td>有来源</td><td>记忆能追溯来源和时间</td></tr><tr><td>有边界</td><td>个人记忆、团队记忆、企业知识分开</td></tr><tr><td>有过期</td><td>过期、不活跃或权限变化后清理</td></tr></tbody></table><h3 id="_4-4-agent-与工具隐私" tabindex="-1">4.4 Agent 与工具隐私 <a class="header-anchor" href="#_4-4-agent-与工具隐私" aria-label="Permalink to &quot;4.4 Agent 与工具隐私&quot;">​</a></h3><p>Agent 会把数据发送给工具。产品必须让用户和企业管理员知道：</p><ul><li>哪些工具被调用；</li><li>发送了哪些字段；</li><li>工具由谁提供；</li><li>是否跨境或出组织；</li><li>是否会写入第三方系统；</li><li>是否可以撤销授权；</li><li>是否有审批和审计。</li></ul><p>工具调用前建议展示：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Agent 准备调用：CRM 查询工具</span></span>
<span class="line"><span>将发送：客户邮箱、公司名、问题摘要</span></span>
<span class="line"><span>目的：查询客户合同状态</span></span>
<span class="line"><span>风险等级：中</span></span>
<span class="line"><span>[允许一次] [始终允许] [拒绝]</span></span></code></pre></div><h3 id="_4-5-删除流程" tabindex="-1">4.5 删除流程 <a class="header-anchor" href="#_4-5-删除流程" aria-label="Permalink to &quot;4.5 删除流程&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户请求删除</span></span>
<span class="line"><span>  → 验证身份</span></span>
<span class="line"><span>  → 前端不可见</span></span>
<span class="line"><span>  → 主库删除 / 匿名化</span></span>
<span class="line"><span>  → 搜索索引和 embedding 删除</span></span>
<span class="line"><span>  → 缓存清理</span></span>
<span class="line"><span>  → 训练 / 评估样例处理</span></span>
<span class="line"><span>  → 第三方处理者通知</span></span>
<span class="line"><span>  → 备份按策略到期清理</span></span>
<span class="line"><span>  → 审计记录保留最小必要信息</span></span></code></pre></div><p>删除不要承诺技术上无法保证的“模型遗忘”。更稳妥的说法是：</p><blockquote><p>我们会删除或去标识化产品系统中的相关数据，并在适用范围内停止将其用于后续训练或评估。已完成训练的模型是否可移除影响需按具体技术和合同说明。</p></blockquote><hr><h2 id="_5-企业级数据保护" tabindex="-1">5. 企业级数据保护 <a class="header-anchor" href="#_5-企业级数据保护" aria-label="Permalink to &quot;5. 企业级数据保护&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>企业价值</th></tr></thead><tbody><tr><td>SSO / SCIM</td><td>身份和入离职管理</td></tr><tr><td>RBAC / ABAC</td><td>最小权限和部门隔离</td></tr><tr><td>数据驻留</td><td>满足地区和行业要求</td></tr><tr><td>零训练承诺</td><td>降低商业机密风险</td></tr><tr><td>DPA / 子处理者清单</td><td>法务和采购准入</td></tr><tr><td>审计日志</td><td>追踪输入、输出、工具和审批</td></tr><tr><td>私有部署 / VPC</td><td>高敏场景的数据控制</td></tr><tr><td>用量和风险报表</td><td>管理成本和合规风险</td></tr><tr><td>保留策略</td><td>自动删除或归档</td></tr></tbody></table><h3 id="_5-1-企业版默认策略建议" tabindex="-1">5.1 企业版默认策略建议 <a class="header-anchor" href="#_5-1-企业版默认策略建议" aria-label="Permalink to &quot;5.1 企业版默认策略建议&quot;">​</a></h3><ul><li>默认不将客户数据用于训练；</li><li>支持关闭历史保存和长期记忆；</li><li>支持组织级连接器白名单；</li><li>高风险工具默认审批；</li><li>管理员可查看审计日志和数据流；</li><li>支持区域级数据处理；</li><li>支持客户删除和导出请求。</li></ul><hr><h2 id="_6-上线检查清单" tabindex="-1">6. 上线检查清单 <a class="header-anchor" href="#_6-上线检查清单" aria-label="Permalink to &quot;6. 上线检查清单&quot;">​</a></h2><ul><li>[ ] 已完成数据流图；</li><li>[ ] 已列出所有模型、工具、MCP server、第三方处理者；</li><li>[ ] 隐私政策包含 AI 数据处理说明；</li><li>[ ] 用户可查看、导出、删除相关数据；</li><li>[ ] 长期记忆可查看、编辑、删除、关闭；</li><li>[ ] 数据用于训练 / 人工审阅有明确控制；</li><li>[ ] RAG 检索有权限过滤；</li><li>[ ] 工具调用有授权、审批和审计；</li><li>[ ] 敏感信息检测和脱敏已实现；</li><li>[ ] 数据留存和备份清理策略已配置；</li><li>[ ] 跨境和数据驻留要求已评估；</li><li>[ ] 高风险场景已完成 DPIA / AIA 或等价评估；</li><li>[ ] 未成年人场景有专项保护；</li><li>[ ] 企业合同、DPA、子处理者清单已准备。</li></ul><hr><h2 id="_7-参考来源" tabindex="-1">7. 参考来源 <a class="header-anchor" href="#_7-参考来源" aria-label="Permalink to &quot;7. 参考来源&quot;">​</a></h2><ul><li>EU AI Act 官方信息：<a href="https://artificialintelligenceact.eu/" target="_blank" rel="noreferrer">https://artificialintelligenceact.eu/</a></li><li>NIST AI Risk Management Framework：<a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noreferrer">https://www.nist.gov/itl/ai-risk-management-framework</a></li><li>NIST Generative AI Profile AI 600-1：<a href="https://www.nist.gov/itl/ai-risk-management-framework/nist-ai-600-1" target="_blank" rel="noreferrer">https://www.nist.gov/itl/ai-risk-management-framework/nist-ai-600-1</a></li><li>OWASP Top 10 for LLM Applications：<a href="https://genai.owasp.org/" target="_blank" rel="noreferrer">https://genai.owasp.org/</a></li><li>Model Context Protocol：<a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/</a></li></ul><hr><blockquote><p><strong>结语</strong>：AI 隐私合规不是在上线前补一份隐私政策，而是从数据流、权限、记忆、工具、审计和删除机制开始的系统性产品设计。</p></blockquote>`,55)])])}const u=a(r,[["render",s]]);export{b as __pageData,u as default};
